private void handleAfterAttacking(LivingDamageEvent.Post ev) {
		LivingEntity target = ev.getEntity();

		this.attackTracker.compute(target.getId(), (id, value) -> {
			if (value == null)
				return Pair.of(target.level().getGameTime(), ev.getNewDamage());

			return Pair.of(target.level().getGameTime(), Math.min(target.getMaxHealth() * 1.5f, ev.getNewDamage() + value.getSecond()));
		});
	}

private void handleEntityKill(LivingDeathEvent ev) {
		LivingEntity target = ev.getEntity();
		Pair<Long, Float> attackEntry = this.attackTracker.get(target.getId());
		float damageDealt = attackEntry == null ? 5f : attackEntry.getSecond();

		if (attackEntry != null)
			this.attackTracker.remove(ev.getEntity().getId());

		if (canGainXp(true))
			PlayerUtil.giveXpToPlayer((ServerPlayer)getPlayer(), type(), getKillXpForEntity(target, damageDealt), false);

		if (this.attackTracker.size() > 10)
			purgeTracker(target.level().getGameTime());
	}

private void purgeTracker(long currentTime) {
		getAttackEntries().removeIf(entry -> entry.getValue().getFirst() < currentTime - 1200);
	}

public Int2ObjectMap.FastEntrySet<Pair<Long, Float>> getAttackEntries() {
		return this.attackTracker.int2ObjectEntrySet();
	}

public boolean hasAttackedEntity(Entity entity) {
		return this.attackTracker.containsKey(entity.getId());
	}

protected float getKillXpForEntity(LivingEntity target, float damageDealt) {
		float xp = PlayerUtil.getTimeBasedXpForLevel(getLevel(true), (int)((Math.min(target.getMaxHealth() * 1.5f, damageDealt) / 16f) * 20));
		double armour = AttributeUtil.getAttributeValue(target, Attributes.ARMOR);
		double toughness = armour > 0 ? AttributeUtil.getAttributeValue(target, Attributes.ARMOR_TOUGHNESS) : 0;
		double speed = AttributeUtil.getAttributeValue(target, Attributes.MOVEMENT_SPEED);

		xp *= 1 + (float)(Mth.square(armour / 30) + Math.pow(toughness / 15, 1.5d));

		if (target.getPersistentData().contains(EntityEvents.SPAWNED_BY_SPAWNER_TAG))
			xp *= 0.25f;

		if (target instanceof FlyingMob || (target instanceof Mob mob && mob.getNavigation() instanceof WaterBoundPathNavigation))
			xp *= 1.1f;

		if (speed > 0.3f)
			xp *= 1.1f;

		if (!EntityUtil.isHostileMob(target))
			xp *= 0.5f;

		if (target.getType().is(Tags.EntityTypes.BOSSES))
			xp *= 1.3f;

		return xp;
	}

default DynamicEventSubscriber<LivingDamageEvent.Post> afterAttacking(Consumer<LivingDamageEvent.Post> handler) {
		return listener(LivingDamageEvent.Post.class, ev -> ev.getSource().getEntity(), handler);
	}

default DynamicEventSubscriber<LivingDeathEvent> onEntityKill(Consumer<LivingDeathEvent> handler) {
		return DynamicEventSubscriber.of(LivingDeathEvent.class, ev -> {
			final Entity selfEntity = getPlayer();

			for (Entity attacker : EntityUtil.getAttackersForMob(ev.getEntity(), entity -> entity != ev.getEntity() && entity == selfEntity)) {
				handler.accept(ev);

				break;
			}
		}, this::isStillValid);
	}

@Override
        protected void tick(TharaflyEntity entity) {
            if (entity.tickCount % 10 == 0)
                entity.doHurtTarget(this.target);

            if (this.target.isCrouching() != this.wasCrouching) {
                this.wasCrouching = this.target.isCrouching();

                if (this.shakes++ >= 10)
                    doStop((ServerLevel)entity.level(), entity, entity.level().getGameTime());
            }
        }

@Override
    public BrainActivityGroup<? extends TharaflyEntity> getFightTasks() {
        return BrainActivityGroup.fightTasks(
                new InvalidateAttackTarget<>().invalidateIf((entity, target) -> !DamageUtil.isAttackable(target) || distanceToSqr(target.position()) > Mth.square(getAttributeValue(Attributes.FOLLOW_RANGE))),
                new SetWalkTargetToAttackTarget<>(),
                new OneRandomBehaviour<>(
                        new AnimatableMeleeAttack<>(getPreAttackTime())
                                .attackInterval(entity -> getAttackSwingDuration() + 2),
                        new TharaflyAttachBehaviour()
                                .startCondition(tharafly -> this.navigation == this.flyingPathNavigation)
                                .runFor(tharafly -> rand().numberBetween(100, 200))
                                .cooldownFor(tharafly -> rand().numberBetween(100, 200))
                ));
    }

@Override
        protected List<Pair<MemoryModuleType<?>, MemoryStatus>> getMemoryRequirements() {
            return MEMORY_REQUIREMENTS;
        }

@Override
        protected boolean checkExtraStartConditions(ServerLevel level, TharaflyEntity entity) {
            LivingEntity target = BrainUtils.getTargetOfEntity(entity);

            if (!(target instanceof Player pl))
                return false;

            this.target = pl;

            return !this.target.isVehicle() && entity.getSensing().hasLineOfSight(this.target) && entity.isWithinMeleeAttackRange(this.target);
        }

@Override
        protected void start(TharaflyEntity entity) {
            this.wasCrouching = this.target.isCrouching();

            entity.startRiding(this.target, true);
            AoANetworking.sendToAllPlayersTrackingEntity(new EntityRidePlayerPacket(entity.getId(), this.target.getUUID(), EntityRidePlayerPacket.Operation.MOUNT), entity);
        }

@Override
        protected boolean shouldKeepRunning(TharaflyEntity entity) {
            return this.target != null && this.target.getFirstPassenger() == entity;
        }

@Override
        protected void stop(TharaflyEntity entity) {
            if (this.target != null)
                AoANetworking.sendToAllPlayersTrackingEntity(new EntityRidePlayerPacket(entity.getId(), this.target.getUUID(), EntityRidePlayerPacket.Operation.DISMOUNT), entity);

            if (this.target == null || this.target == entity.getVehicle())
                entity.stopRiding();

            BrainUtils.setForgettableMemory(entity, MemoryModuleType.ATTACK_COOLING_DOWN, true, 40);

            this.target = null;
            this.shakes = 0;
            this.wasCrouching = false;
        }

@Override public void inventoryTick(ItemStack stack, Level level, Entity entity, int slotId, boolean isSelected) {
        if(isSelected && (level.getGameTime() & 1L) == 0 && level instanceof ServerLevel server) {
            int cooldown = stack.get(DataComponentRegistry.weaponAbility);
            if(cooldown > 0) {
                stack.set(DataComponentRegistry.weaponAbility, cooldown - 1);
                float f = stack.get(DataComponentRegistry.weaponPower);
                if(entity instanceof Player player) {
                    ItemStack itemstack = player.getProjectile(stack);
                    if(infinityArrow != null && (itemstack.isEmpty() || itemstack.is(infinityArrow.get()))) itemstack = new ItemStack(infinityArrow.get());
                    if(itemstack.isEmpty()) return;
                    List<ItemStack> list = draw(stack, itemstack, player);
                    if(!list.isEmpty()) shoot(server, player, player.getUsedItemHand(), stack, list, f * 3F * speedScale, 8, f == 1, null);
                    level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundRegistry.INFERNO_BOW_SHOOT.get(), PLAYERS, 1, 1 / (level.getRandom().nextFloat() * .4F + 1.2F) + f * .5F);
                    player.awardStat(ITEM_USED.get(this));
                } else if(entity instanceof LivingEntity living) {
                    shoot(server, living, living.getUsedItemHand(), stack, List.of(new ItemStack(inferno_arrow.get())), f * 3F * speedScale, 8, f == 1, living instanceof Mob mob ? mob.getTarget() : null);
                    living.playSound(SoundRegistry.INFERNO_BOW_SHOOT.get(), 1, 1 / (level.getRandom().nextFloat() * .4F + .8F));
                }
            }
        }
    }

@Override public void releaseUsing(ItemStack stack, Level level, LivingEntity living, int timeLeft) {
        int i;
        if(living instanceof Player player) {
            ItemStack itemstack = player.getProjectile(stack);
            if(infinityArrow != null && (itemstack.isEmpty() || itemstack.is(infinityArrow.get()))) itemstack = new ItemStack(infinityArrow.get());
            if(itemstack.isEmpty()) return;
            i = EventHooks.onArrowLoose(stack, level, player, (getUseDuration(stack, player) - timeLeft) * 72000 / useDuration, true);
            player.getCooldowns().addCooldown(this, 60);
        } else i = (getUseDuration(stack, living) - timeLeft) * 72000 / useDuration;
        if(i < 0) return;
        float f = getPowerForTime(i);
        if(f >= .1F) {
            stack.set(DataComponentRegistry.weaponAbility, 9);
            stack.set(DataComponentRegistry.weaponPower, f);
        }
    }

@Override protected void shoot(ServerLevel level, LivingEntity shooter, InteractionHand hand, ItemStack weapon, List<ItemStack> projectileItems, float velocity, float inaccuracy, boolean isCrit, @Nullable LivingEntity target) {
        float f = EnchantmentHelper.processProjectileSpread(level, weapon, shooter, 0);
        float f1 = projectileItems.size() == 1 ? 0 : 2 * f / (projectileItems.size() - 1);
        float f2 = ((projectileItems.size() - 1) % 2) * f1 / 2;
        float f3 = 1;
        for(int i = 0; i < projectileItems.size(); ++i) {
            ItemStack itemstack = projectileItems.get(i);
            if(!itemstack.isEmpty()) {
                float f4 = f2 + f3 * ((i + 1) >> 1) * f1;
                f3 = -f3;
                Projectile projectile = createProjectile(level, shooter, weapon, itemstack, isCrit);
                shootProjectile(shooter, projectile, i, velocity, inaccuracy, f4, target);
                level.addFreshEntity(projectile);
                PacketDistributor.sendToPlayersTrackingEntity(projectile, new AccurateSetMotionPacket(projectile.getId(), projectile.getDeltaMovement()));
                weapon.hurtAndBreak(getDurabilityUse(itemstack), shooter, LivingEntity.getSlotForHand(hand));
                if(weapon.isEmpty()) break;
            }
        }
    }

@Override public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        ItemStack itemstack = player.getItemInHand(hand);
        boolean flag = !player.getProjectile(itemstack).isEmpty();
        InteractionResultHolder<ItemStack> ret = EventHooks.onArrowNock(itemstack, level, player, hand, flag);
        if(ret != null) return ret;
        else if(infinityArrow == null && !player.hasInfiniteMaterials() && !flag) return InteractionResultHolder.fail(itemstack);
        else {
            player.startUsingItem(hand);
            return InteractionResultHolder.consume(itemstack);
        }
    }

@Override
	public void inventoryTick(ItemStack stack, Level world, Entity entity, int slot, boolean selected) {
		super.inventoryTick(stack, world, entity, slot, selected);
		if (!(entity instanceof Player player)) {
			return;
		}

		// Initialize timer for new items
		if (!ItemNBTHelper.verifyExistance(stack, TAG_LAST_TRIGGER)) {
			ItemNBTHelper.setLong(stack, TAG_LAST_TRIGGER, world.getGameTime());
		}

		MobEffectInstance haste = player.getEffect(MobEffects.DIG_SPEED);
		float check = haste == null ? 0.16666667F : haste.getAmplifier() == 1 ? 0.5F : 0.4F;

		long timeSinceLast = world.getGameTime() - ItemNBTHelper.getLong(stack, TAG_LAST_TRIGGER, world.getGameTime());
		if (timeSinceLast > INTERVAL && player.getMainHandItem() == stack && player.attackAnim == check && !world.isClientSide) {
			ItemNBTHelper.setLong(stack, TAG_LAST_TRIGGER, world.getGameTime());
			summonFallingStar(stack, world, player);
		}
	}

private void summonFallingStar(ItemStack stack, Level world, Player player) {
		BlockHitResult pos = ToolCommons.raytraceFromEntity(player, 48, false);
		if (pos.getType() == HitResult.Type.BLOCK) {
			Vec3 posVec = Vec3.atLowerCornerOf(pos.getBlockPos());
			Vec3 motVec = new Vec3((0.5 * Math.random() - 0.25) * 18, 24, (0.5 * Math.random() - 0.25) * 18);
			posVec = posVec.add(motVec);
			motVec = motVec.normalize().reverse().scale(1.5);

			FallingStarEntity star = new FallingStarEntity(player, world);
			star.setPos(posVec.x, posVec.y, posVec.z);
			star.setDeltaMovement(motVec);
			world.addFreshEntity(star);

			if (!world.isRaining()
					&& Math.abs(world.getDayTime() - 18000) < 1800
					&& Math.random() < 0.125) {
				FallingStarEntity bonusStar = new FallingStarEntity(player, world);
				bonusStar.setPos(posVec.x, posVec.y, posVec.z);
				bonusStar.setDeltaMovement(motVec.x + Math.random() - 0.5,
						motVec.y + Math.random() - 0.5, motVec.z + Math.random() - 0.5);
				world.addFreshEntity(bonusStar);
			}

			stack.hurtAndBreak(1, player, p -> p.broadcastBreakEvent(InteractionHand.MAIN_HAND));
			world.playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.starcaller, SoundSource.PLAYERS, 1F, 1F);
		}
	}

@Override
	public void tick() {
		super.tick();

		if (!hasBeenInAir && !level().isClientSide) {
			var bs = getFeetBlockState();
			hasBeenInAir = bs.isAir() || isInWater() || isInLava();
		}

		float dist = 1.5F;
		SparkleParticleData data = SparkleParticleData.sparkle(2F, 1F, 0.4F, 1F, 6);
		for (int i = 0; i < 10; i++) {
			float xs = (float) (Math.random() - 0.5) * dist;
			float ys = (float) (Math.random() - 0.5) * dist;
			float zs = (float) (Math.random() - 0.5) * dist;
			level().addAlwaysVisibleParticle(data, getX() + xs, getY() + ys, getZ() + zs, 0, 0, 0);
		}

		Entity thrower = getOwner();
		if (!level().isClientSide && thrower != null) {
			AABB axis = new AABB(getX(), getY(), getZ(), xOld, yOld, zOld).inflate(2);
			List<LivingEntity> entities = level().getEntitiesOfClass(LivingEntity.class, axis);
			for (LivingEntity living : entities) {
				if (living == thrower) {
					continue;
				}

				if (living.hurtTime == 0) {
					onHit(new EntityHitResult(living));
					return;
				}
			}
		}

		if (tickCount > 200) {
			discard();
		}
	}

@Override
	protected void onHitEntity(@NotNull EntityHitResult hit) {
		super.onHitEntity(hit);
		Entity e = hit.getEntity();
		// Blacklisting villagers since trading with them counts as a "swing" and will summon a star.
		if (e instanceof Villager) {
			return;
		}
		if (!level().isClientSide) {
			if (e != getOwner() && e.isAlive()) {
				if (getOwner() instanceof Player player) {
					e.hurt(player.damageSources().playerAttack(player), Math.random() < 0.25 ? 10 : 5);
				} else {
					e.hurt(e.damageSources().generic(), Math.random() < 0.25 ? 10 : 5);
				}
			}
			discard();
		}
	}

@Override
	protected void onHitBlock(BlockHitResult hit) {
		super.onHitBlock(hit);
		if (!level().isClientSide) {
			BlockPos bpos = hit.getBlockPos();
			BlockState state = level().getBlockState(bpos);
			if (hasBeenInAir) {
				if (BotaniaConfig.common().blockBreakParticles() && !state.isAir()) {
					this.level().levelEvent(2001, bpos, Block.getId(state));
				}
				discard();
			}
		}
	}

@Override
	protected void addAdditionalSaveData(CompoundTag tag) {
		super.addAdditionalSaveData(tag);
		tag.putBoolean(TAG_HAS_BEEN_IN_AIR, hasBeenInAir);
	}

@Override
	protected void readAdditionalSaveData(CompoundTag tag) {
		super.readAdditionalSaveData(tag);
		this.hasBeenInAir = tag.getBoolean(TAG_HAS_BEEN_IN_AIR);
	}

public static boolean damageThroughIframes(Entity targetEntity, DamageSource damageSource, float damage) {
        if (targetEntity instanceof PlayerEntity player && (player.isCreative() || player.isSpectator()))
            return false;
        if (IgnoredEntities.isIgnored(targetEntity))
            return false;
        int iframes = targetEntity.timeUntilRegen;
        try {
            targetEntity.timeUntilRegen = 0;
            return targetEntity.damage(damageSource, damage);
        } finally {
            targetEntity.timeUntilRegen = iframes;
        }
    }

public static void runSuppressed(Runnable runnable) {
        SUPPRESS_IMPLICITS.set(true);
        try {
            runnable.run();
        } finally {
            SUPPRESS_IMPLICITS.set(false);
        }
    }
